            { q: "Simbol belah ketupat pada flowchart menyatakan ...", o: ["Proses","Input/output","Keputusan (percabangan)","Mulai/akhir"], a: 2, bahas: "Belah ketupat dipakai untuk kondisi benar/salah yang bercabang." }
