        {
          id: "smk-tkj-5",
          judul: "Jaringan Nirkabel dan Standar Wi-Fi",
          ringkas: "Memilih frekuensi, kanal, dan standar Wi-Fi serta mengoptimalkan sinyal dan keamanan jaringan nirkabel.",
          materi: "<p>Jaringan nirkabel (wireless) memakai gelombang radio untuk menghubungkan perangkat tanpa kabel. Standar IEEE 802.11 menentukan kecepatan, frekuensi, dan jarak tempuh. Pemahaman perbedaan frekuensi 2,4 GHz dan 5 GHz menjadi dasar pemilihan perangkat dan penataan jaringan yang stabil.</p><h4>Perbandingan Frekuensi</h4><table><thead><tr><th>Aspek</th><th>2,4 GHz</th><th>5 GHz</th></tr></thead><tbody><tr><td>Jarak jauh</td><td>Menembus dinding lebih baik</td><td>Terbatas, lebih mudah terhalang</td></tr><tr><td>Kecepatan</td><td>Lebih lambat, kanal sedikit</td><td>Lebih cepat, kanal lebih banyak</td></tr><tr><td>Gangguan</td><td>Penuh (bluetooth, perangkat rumah)</td><td>Lebih sepi</td></tr><tr><td>Cocok untuk</td><td>Luas dan tembok tebal</td><td>Streaming dan trafik padat</td></tr></tbody></table><h4>Standar Wi-Fi</h4><ul><li>802.11n (Wi-Fi 4): gabungan 2,4 dan 5 GHz, hingga 600 Mbps.</li><li>802.11ac (Wi-Fi 5): khusus 5 GHz, lebih cepat dan hemat daya.</li><li>802.11ax (Wi-Fi 6): efisien pada banyak perangkat bersamaan.</li></ul><h4>Penataan Sinyal</h4><ol><li>Pilih kanal yang tidak dipakai tetangga; pada 2,4 GHz hanya kanal 1, 6, dan 11 yang tidak saling tumpang tindih.</li><li>Letakkan access point tinggi dan terbuka, jauh dari perangkat logam dan perangkat bermotor.</li><li>Atur lebar kanal: 20 MHz untuk stabilitas jarak jauh, 40/80 MHz untuk kecepatan dekat.</li><li>Uji kecepatan di beberapa titik untuk menemukan area sinyal lemah.</li></ol><h4>Keamanan Nirkabel</h4><p>Gunakan enkripsi WPA3 (atau WPA2 bila perangkat lama) dengan kata sandi kuat. SSID tersembunyi bukan pengaman utama; yang menentukan adalah enkripsi dan manajemen akses. Untuk tamu, sediakan jaringan terpisah agar perangkat tamu tidak menjangkau perangkat internal.</p><blockquote>Sinyal kuat bukan jaminan jaringan baik: kanal yang tepat lebih berharga daripada daya pancar maksimum.</blockquote>",
          soal: [
            { q: "Keunggulan frekuensi 2,4 GHz dibanding 5 GHz adalah...", o: ["kecepatan lebih tinggi", "kemampuan menembus dinding lebih baik", "kanal lebih banyak", "gangguan lebih sedikit"], a: 1, bahas: "Frekuensi lebih rendah memiliki panjang gelombang lebih panjang sehingga lebih baik menembus penghalang." },
            { q: "Pada 2,4 GHz, kanal yang tidak saling tumpang tindih adalah...", o: ["1, 6, dan 11", "2, 3, dan 4", "semua kanal bebas dipilih", "hanya kanal 14"], a: 0, bahas: "Ketiga kanal ini berjarak cukup jauh sehingga tidak saling mengganggu antarjaringan tetangga." },
            { q: "Standar Wi-Fi yang dikenal sebagai Wi-Fi 6 adalah...", o: ["802.11n", "802.11ac", "802.11ax", "802.11b"], a: 2, bahas: "802.11ax (Wi-Fi 6) dioptimalkan untuk efisiensi saat banyak perangkat terhubung bersamaan." },
            { q: "Penempatan access point yang paling tepat adalah...", o: ["di lantai dalam kotak logam", "tinggi, terbuka, dan jauh dari perangkat bermotor", "di balik kulkas", "di dalam lemari besi"], a: 1, bahas: "Posisi tinggi dan terbuka meminimalkan halangan; logam dan motor memantulkan serta menyerap gelombang radio." },
            { q: "Enkripsi jaringan nirkabel yang paling aman saat ini adalah...", o: ["WEP", "WPA3", "tanpa kata sandi", "SSID tersembunyi"], a: 1, bahas: "WEP sudah rapuh dan mudah dibobol; WPA3 memperkuat pertukaran kunci dan proteksi kata sandi." },
            { q: "Untuk menampung banyak perangkat tamu tanpa membahayakan jaringan internal, yang tepat adalah...", o: ["membagikan kata sandi utama", "membuat jaringan tamu terpisah", "mematikan firewall", "menonaktifkan enkripsi"], a: 1, bahas: "Jaringan tamu yang terisolasi mencegah perangkat asing mengakses perangkat dan berkas internal." }
,
            { q: "Standar Wi-Fi yang beroperasi pada frekuensi 5 GHz umumnya memberi ...", o: ["Kecepatan lebih tinggi dan interferensi lebih rendah","Jarak lebih jauh tanpa hambatan","Biaya lebih mahal tanpa keuntungan","Kecepatan lebih lambat"], a: 0, bahas: "Frekuensi 5 GHz punya kanal lebih banyak sehingga kecepatan dan kepadatan trafik lebih baik." },
            { q: "Kanal Wi-Fi yang tidak saling tumpang tindih pada 2,4 GHz adalah ...", o: ["Kanal 1, 6, dan 11","Kanal 2, 3, dan 4","Semua kanal saling tumpang","Kanal 13 saja"], a: 0, bahas: "Kanal 1, 6, 11 dipilih karena jarak frekuensinya cukup jauh agar tidak overlap." },
            { q: "Agar jaringan nirkabel aman, enkripsi yang direkomendasikan saat ini adalah ...", o: ["WPA3","WEP","Tanpa enkripsi","WPA lama tanpa sandi"], a: 0, bahas: "WPA3 terbaru paling kuat; WEP sudah terbukti mudah ditembus." },
            { q: "Akses point bertugas ...", o: ["Menyambung perangkat nirkabel ke jaringan kabel","Memotong kabel","Menyimpan daya listrik","Mengubah sinyal ke suara"], a: 0, bahas: "AP menjadi jembatan antara perangkat Wi-Fi dan jaringan bertembaga." },
            { q: "Posisi router yang paling baik untuk sinyal merata adalah ...", o: ["Tengah ruangan dan tinggi","Di bawah tempat tidur","Di sudut tertutup logam","Dalam lemari besi"], a: 0, bahas: "Sinyal menyebar merata ke segala arah; hindari penghalang logam dan dinding tebal." }
                    ]
        },
        {
          id: "smk-tkj-6",
          judul: "Routing dan Switching Lanjut",
          ringkas: "Menganalisis tabel rute statis-dinamis, VLAN, STP, serta perbaikan jaringan dengan alat uji.",
          materi: "<p>Switch menghubungkan perangkat dalam satu jaringan lokal dan meneruskan frame berdasarkan alamat MAC, sedangkan router menghubungkan antarjaringan dan memilih rute berdasarkan alamat IP. Pada jaringan perusahaan, keduanya bekerja bersama dengan pengaturan VLAN agar trafik terorganisir dan aman.</p><h4>VLAN dan Trunking</h4><p>VLAN (Virtual LAN) membagi satu switch menjadi beberapa jaringan logis tanpa memisah perangkat secara fisik. Departemen keuangan dan pemasaran dapat berada di VLAN berbeda sehingga trafik terpisah. Trunk port membawa trafik banyak VLAN sekaligus dengan penandaan (tagging) 802.1Q.</p><h4>Spanning Tree Protocol</h4><p>STP mencegah loop broadcast pada topologi redundan dengan menonaktifkan jalur berlebih hingga diperlukan. Tanpa STP, frame berputar tanpa henti sehingga jaringan melambat sampai lumpuh. Varian modern seperti RSTP mengembalikan jalur cadangan dalam hitungan detik saat jalur utama putus.</p><h4>Rute Statis dan Dinamis</h4><table><thead><tr><th>Jenis</th><th>Karakteristik</th><th>Cocok untuk</th></tr></thead><tbody><tr><td>Statis</td><td>Ditulis manual, tidak berubah sendiri</td><td>Jalur tetap, jaringan kecil</td></tr><tr><td>Dinamis (OSPF, RIP)</td><td>Belajar dan menyesuaikan otomatis</td><td>Jaringan bertumbuh, banyak jalur</td></tr></tbody></table><h4>Alat Uji Jaringan</h4><ul><li>Cable tester dan toner penelusur kabel untuk memeriksa fisik dan jalur kabel.</li><li>Ping dan traceroute untuk menguji jarak serta menemukan titik putus.</li><li>Packet analyzer untuk melihat isi trafik dan mencari penyebab kelambatan.</li><li>Loopback test untuk memeriksa kinerja satu jalur transmisi.</li></ul><blockquote>Redundansi tanpa pengaturan justru menimbulkan masalah; STP adalah penjaga topologi berlebih.</blockquote>",
          soal: [
            { q: "Perangkat yang meneruskan frame berdasarkan alamat MAC adalah...", o: ["router", "switch", "modem", "access point"], a: 1, bahas: "Switch bekerja pada lapisan data link dan memetakan alamat MAC ke port tujuannya." },
            { q: "Fungsi utama STP pada jaringan adalah...", o: ["menambah kecepatan transfer", "mencegah loop broadcast pada topologi redundan", "mengganti IP otomatis", "mengenkripsi trafik"], a: 1, bahas: "Tanpa STP, jalur sirkuit menimbulkan frame berputar tanpa henti yang membanjiri jaringan." },
            { q: "Trunk port pada switch berfungsi untuk...", o: ["menyambung perangkat akhir saja", "membawa trafik banyak VLAN sekaligus", "mematikan VLAN", "menambah kecepatan kabel"], a: 1, bahas: "Trunk menandai frame dengan 802.1Q sehingga satu kabel dapat membawa beberapa VLAN terpisah." },
            { q: "Rute statis paling cocok dipakai pada...", o: ["jaringan yang terus berubah", "jalur tetap dan jaringan kecil", "internet global", "jaringan tanpa router"], a: 1, bahas: "Rute statis sederhana dan dapat diprediksi, tetapi harus diperbarui manual bila topologi berubah." },
            { q: "Perangkat yang menghubungkan dua jaringan lokal yang berbeda dan memilih rute adalah...", o: ["switch", "router", "hub", "repeater"], a: 1, bahas: "Router bekerja pada lapisan jaringan, memutuskan rute berdasarkan alamat IP antarjaringan." },
            { q: "Alat yang digunakan untuk menemukan titik putus jalur paket adalah...", o: ["traceroute", "cutter tang", "obeng", "kabel roll"], a: 0, bahas: "traceroute menampilkan tiap perangkat yang dilalui paket sehingga titik berhenti dapat diketahui." }
,
            { q: "Tabel rute statis dibuat ...", o: ["Otomatis oleh protokol dinamis","Manual oleh administrator","Otomatis oleh DNS","Oleh pengguna akhir"], a: 1, bahas: "Rute statis dikonfigurasi manual dan cocok untuk jaringan kecil yang tetap." },
            { q: "Fungsi VLAN adalah ...", o: ["Membagi jaringan logis menjadi segmen terpisah","Memperbesar daya CPU","Mengubah IP otomatis","Memantau suhu ruangan"], a: 0, bahas: "VLAN memisahkan broadcast domain tanpa memisahkan perangkat secara fisik." },
            { q: "STP (Spanning Tree Protocol) berfungsi untuk ...", o: ["Mencegah loop pada jaringan bertopologi cincin/ring","Mempercepat unduhan","Mengenkripsi data","Menambah IP address"], a: 0, bahas: "STP memblokir jalur berlebih sehingga broadcast loop tidak terjadi." },
            { q: "Alat uji untuk memeriksa apakah kabel jaringan terhubung baik adalah ...", o: ["LAN tester","Oscilloscope","Solder","Multimeter biasa saja"], a: 0, bahas: "LAN tester/cable tester memeriksa urutan dan kontak tiap pasangan kawat." },
            { q: "Perintah untuk melihat tabel rute pada router/PC Linux adalah ...", o: ["route -n atau ip route","ls -l","ping saja","chmod +x"], a: 0, bahas: "route -n / ip route menampilkan daftar rute yang aktif di perangkat." },
            { q: "Ketika satu jalur uplink putus dan jalur cadangan mengambil alih, itu disebut ...", o: ["Failover","Format","Firewall","Firmware"], a: 0, bahas: "Failover adalah pengalihan otomatis ke jalur cadangan saat jalur utama gagal." }
                    ]
        }
